        expect(document.querySelector(".mx_Tooltip_visible")).toHaveTextContent("!room:example.org");
        fireEvent.mouseLeave(pill);
        expect(document.querySelector(".mx_Tooltip_visible")).toBeNull();
    });

    it("opens a local member from a message and marks a mention of the current user", () => {
