        rerender(<Pill url={`https://matrix.to/#/${userId}`} room={room} />);
        expect(container.querySelector("span.mx_UserPill")).toBeInTheDocument();
        fireEvent.click(container.querySelector("span.mx_UserPill")!);
        expect(dispatch).toHaveBeenCalledTimes(1);
        dispatch.mockRestore();
    });

    it("uses the full user ID until a remote profile supplies a display name", async () => {
        (room.getMember as jest.Mock).mockReturnValue(null);
        (client.getProfileInfo as jest.Mock).mockResolvedValue({ displayname: "Remote name" });
        const { container } = render(<Pill url="https://matrix.to/#/@remote:example.org" room={room} />);
        expect(container.querySelector(".mx_Pill_linkText")).toHaveTextContent("@remote:example.org");
        await waitFor(() => expect(container.querySelector(".mx_Pill_linkText")).toHaveTextContent("Remote name"));
    });
});
